using System.IO;using System.Windows.Media.Imaging;using GymOS.Windows;
static class Program{
 [STAThread] static void Main(string[] args){_ = new System.Windows.Application();var root=Path.Combine(Path.GetTempPath(),"gymos-brand-test-"+Guid.NewGuid());Directory.CreateDirectory(root);try{var logo="data:image/png;base64,"+Convert.ToBase64String(File.ReadAllBytes(args[0]));var store=new DesktopBranding(root);if(store.Load()!=null)throw new Exception("Unexpected cached brand");var brand=new ClubBrand("synthetic-owner","Synthetic Club",logo);var first=store.Apply(brand);if(first.image?.PixelWidth!=512||first.image.PixelHeight!=512||first.icon==null||!File.Exists(first.icon))throw new Exception("Icon not produced");using(var stream=File.OpenRead(first.icon)){var icon=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);if(icon.Frames[0].PixelWidth!=256)throw new Exception("Invalid ICO");}var embedded=BitmapFrame.Create(new Uri("pack://application:,,,/GymOS;component/SplashLogo.png"));if(embedded.PixelWidth!=512)throw new Exception("Default splash uses low-resolution icon");
if(store.Load()!=brand)throw new Exception("Brand not restored on startup");var next=store.Apply(brand with{Owner="other-owner"});if(next.icon==first.icon)throw new Exception("Cross-tenant icon path");foreach(var invalid in new[]{brand with{Logo="https://evil.invalid/icon.png"},brand with{Owner=""},brand with{Logo="data:image/png;base64,AA=="},brand with{Name="bad\nname"}}){bool rejected=false;try{store.Apply(invalid);}catch{rejected=true;}if(!rejected)throw new Exception("Unsafe branding accepted");}// The splash source keeps its aspect ratio and never upscales a small upload to 256.
var small=BitmapSource.Create(96,48,96,96,System.Windows.Media.PixelFormats.Bgra32,null,new byte[96*48*4],96*4);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(small));using(var output=new MemoryStream()){enc.Save(output);var result=store.Apply(brand with{Logo="data:image/png;base64,"+Convert.ToBase64String(output.ToArray())},false);if(result.image?.PixelWidth!=96||result.image.PixelHeight!=48)throw new Exception("Small logo was upscaled or stretched");}
store.Apply(brand with{Logo=null});if(store.Load()?.Logo!=null)throw new Exception("Logo removal not persisted");store.Clear();if(store.Load()!=null)throw new Exception("Brand reset failed");foreach(var url in new[]{"javascript:alert(1)","file:///C:/data","https://evil.invalid/","https://open.spotify.com.evil.invalid/","https://user:pass@open.spotify.com/","https://open.spotify.com:444/"})if(MusicNavigation.Initial(url))throw new Exception("Unsafe music initial URL accepted");if(!MusicNavigation.Initial("https://play.anghami.com/song/123")||MusicNavigation.Profile("owner-a|main")==MusicNavigation.Profile("owner-b|main"))throw new Exception("Music profile isolation failed");
if(!MusicNavigation.MayRequestAutoplay("https://open.spotify.com/track/abc",true)||MusicNavigation.MayRequestAutoplay("https://evil.invalid",true)||MusicNavigation.MayRequestAutoplay("https://open.spotify.com",false))throw new Exception("Unsafe autoplay permission scope");
if(args.Length>1)System.Windows.Application.Current.Run(new System.Windows.Window{Content=new MusicPane(args[1],"synthetic-music-test|main"),Width=420,Height=560});Console.WriteLine("PASS: music URL allowlist and tenant-scoped profile; high-resolution splash preserves 512px source independently of 256px shortcut icon; Windows PNG validation, ICO decode, startup restore, tenant-specific cache path, logo removal and reset");}finally{Directory.Delete(root,true);}}
}
